```typescript
import { type KeyofBase, noop } from "ts-essentials";

export async function* myOn<T extends Record<KeyofBase, unknown[]>, Key extends keyof T>(
  emitter: EventEmitter<T>,
  eventName: Key,
  signal?: AbortSignal,
): AsyncIterableIterator<T[Key]> {
  type Value = T[Key];
  const abortPromise =
    signal == null
      ? new Promise<never>(noop)
      : new Promise<never>((_, reject) => {
          signal.addEventListener("abort", () => reject(signal.reason));
        });

  const stream: Value[] = [];
  let next: ((value: Value) => void) | null = null;

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (emitter.on as any)(eventName, listener);

  try {
    while (true) {
      if (stream.length > 0) {
        yield stream.shift()!;
      } else {
        const promise = new Promise<Value>((resolve) => (next = resolve));
        yield await Promise.race([promise, abortPromise]);
      }
    }
  } finally {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (emitter.off as any)(eventName, listener);
  }

  function listener(...value: Value) {
    if (next !== null) {
      next(value);
      next = null!;
    } else {
      stream.push(value);
    }
  }
}
