  }

  interface TomlTransaction {
    id: string;
    card?: string;
    date: string;
    amount: number;
    'statement-description': string;
    description?: string;
    category?: string;
    transfer?: boolean;
    income?: boolean;
    tags?: Tag[];
    attachment?: string;
    comment?: string;
  }

  // Prepare TOML data structure
  const tomlData: TomlStatement = {
    id: id.replace('-', '/'),
    account: id.split('-')[0]!,
    date: statementDate,
    total,
    transactions: []
  };

  // Convert transactions
  transactionsArray.getElements().forEach((transaction) => {
    const transactionObj: Transaction = {
      id: '',
      accountId: '',
      amount: 0,
      date: '',
      statementDescription: '',
    };

    transaction.asKindOrThrow(SyntaxKind.ObjectLiteralExpression).getProperties().forEach((prop) => {
      const propName = prop.asKindOrThrow(SyntaxKind.PropertyAssignment).getNameNode().getText();
      const propValue = prop.asKindOrThrow(SyntaxKind.PropertyAssignment).getInitializerOrThrow();

      switch (propName) {
        case 'id':
          transactionObj.id = propValue.asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue().replace('-', '/');
          break;
        case 'card':
          transactionObj.card = propValue.asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue();
          break;
        case 'date': {
          const dateString = propValue.asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue();
          const [year, month, day] = dateString.split('-');
          if (!year || !month || !day) {
            throw new Error(`Invalid date format: ${dateString}`);
          }
          transactionObj.date = `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
          break;
        }
        case 'amount':
          transactionObj.amount = evaluateExpression(propValue);
          break;
        case 'statementDescription':
          transactionObj.statementDescription = propValue.asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue();
          break;
        case 'description':
          transactionObj.description = propValue.asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue();
          break;
        case 'categoryId':
          transactionObj.categoryId = propValue.asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue();
          break;
        case 'accountId':
          // Ignore accountId property
          break;
        case 'transfer':
          transactionObj.transfer = propValue.asKindOrThrow(SyntaxKind.TrueKeyword).getLiteralValue();
          break;
        case 'income':
          transactionObj.income = propValue.asKindOrThrow(SyntaxKind.TrueKeyword).getLiteralValue();
          break;
        case 'tags':
          // TODO: handle tags that are objects
          transactionObj.tags = propValue.asKindOrThrow(SyntaxKind.ArrayLiteralExpression)
            .getElements()
            .map((tag) =>
              tag.isKind(SyntaxKind.StringLiteral)
                ? tag.getLiteralValue()
                : {
                  name: tag.asKindOrThrow(SyntaxKind.ObjectLiteralExpression).getProperty('name')!
                    .asKindOrThrow(SyntaxKind.PropertyAssignment).getInitializerOrThrow().asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue(),
                  year: tag.asKindOrThrow(SyntaxKind.ObjectLiteralExpression).getProperty('year')!
                    .asKindOrThrow(SyntaxKind.PropertyAssignment).getInitializerOrThrow().asKindOrThrow(SyntaxKind.NumericLiteral).getLiteralValue(),
                }
            );
          break;
        case 'attachment':
          transactionObj.attachment = propValue.asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue();
          break;
        case 'comment':
          transactionObj.comment = propValue.asKindOrThrow(SyntaxKind.StringLiteral).getLiteralValue();
          break;
        default:
          throw new Error(`Unsupported property: ${propName}`);
      }
    });

    tomlData.transactions.push({
      id: transactionObj.id,
      card: transactionObj.card,
      date: transactionObj.date,
      amount: transactionObj.amount,
      'statement-description': transactionObj.statementDescription,
      description: transactionObj.description,
      category: transactionObj.categoryId,
      transfer: transactionObj.transfer,
      income: transactionObj.income,
      attachment: transactionObj.attachment,
      comment: transactionObj.comment,
    });
  });

  // check that the transaction amounts sum to the total
  const transactionTotal = tomlData.transactions.reduce((acc, transaction) => acc + transaction.amount, 0);
  if (transactionTotal !== total) {
    throw new Error(`Transaction total ${transactionTotal} does not match statement total ${total}`);
  }

  // Write to TOML file
  const tomlString = toml.stringify(tomlData as any);

  // fix e.g. ` = 123_456` to ` = 1_234_56`
  const fixedTomlString = tomlString.replace(/ = ([+-]?)([_\d]+)/g, (_, sign, number) => {
    let fixedNumber = number.replace(/_/g, '');

    for (let i = 2; i < fixedNumber.length; i += 4) {
      fixedNumber = fixedNumber.slice(0, -i) + '_' + fixedNumber.slice(-i);
    }

    return ` = ${sign}${fixedNumber}`;
  });

  fs.writeFileSync(outputFile, fixedTomlString);

  console.log(`Converted ${inputFile} to ${outputFile}`);
}

// Usage example
function main() {
  const inputDir = process.argv[2] || '.';

  // Find and convert all .ts files in the input directory
  fs.readdirSync(inputDir)
    .filter(file => file.endsWith('.ts') && !file.startsWith('index'))
    .forEach(file => {
      const inputFile = path.join(inputDir, file);
      const outputFile = path.join(inputDir, file.replace('.ts', '.toml'));
      convertTsToToml(inputFile, outputFile);
    });
}

// Only run main if this script is being run directly
if (require.main === module) {
  main();
}

export { convertTsToToml };
