  encoding: 'hex',
  expiresIn: 60 * 60 * 1000,
});
console.log('Hex token:', hexToken);

// Verify the hex token with matching encoding
console.log('\nVerifying hex token with matching hex encoding...');
const hexVerifyResult = Bun.CSRF.verify(hexToken, {
  secret,
  encoding: 'hex',
