console.log('Hex verification result:', hexVerifyResult);

// Verify the hex token WITHOUT specifying encoding (should fail)
console.log('\nVerifying hex token WITHOUT specifying encoding...');
const hexVerifyResultDefault = Bun.CSRF.verify(hexToken, {
  secret,
});
console.log(
  'Hex verification without encoding result:',
  hexVerifyResultDefault,
);
```

