defineOptions({ inheritAttrs: false });

const props = defineProps({
  code: { type: String, required: true },
  language: { type: String, required: true },
});
const preAttrs = ref({});
const innerHTML = ref('');
const fullHtml = await codeToHtml(props.code, {
  lang: props.language,
  themes: {
    light: 'github-light',
    dark: 'github-dark',
  },
});
const fragment = parseFragment(fullHtml);
const preNode = fragment.childNodes.find((node) => node.nodeName === 'pre');

if (preNode && 'attrs' in preNode) {
  for (const attr of preNode.attrs) {
    preAttrs.value[attr.name] = attr.value;
  }

  const codeNode = preNode.childNodes.find((node) => node.nodeName === 'code');
  innerHTML.value =
    (codeNode
      ? serialize(codeNode)
      : preNode.childNodes
          .map(serialize)
          .join('')) || '';
}
</script>

