### What is the feature you are proposing to solve the problem?

This is a simple implementation

 ```ts
export class RWMutex {
  private readCount = 0
  private writePending = 0
  private isWriting = false
  private readonly spinDelay: number

  constructor(
    options: {
      spinDelayMs?: number
    } = {},
  ) {
    this.spinDelay = options.spinDelayMs ?? 0.1
  }

  rLock(): void {
    while (this.isWriting || this.writePending > 0) {
      Bun.sleepSync(this.spinDelay)
    }
    this.readCount++
  }

  rUnlock(): void {
    if (this.readCount <= 0) {
      throw new Error('RWMutex: rUnlock of unlocked mutex')
    }
    this.readCount--
  }

  lock(): void {
    this.writePending++

    while (this.readCount > 0 || this.isWriting) {
      Bun.sleepSync(this.spinDelay)
    }

    this.writePending--
    this.isWriting = true
  }

  unlock(): void {
    if (!this.isWriting) {
      throw new Error('RWMutex: unlock of unlocked mutex')
    }
    this.isWriting = false
  }

  tryRLock(): boolean {
    if (this.isWriting || this.writePending > 0) {
      return false
    }
    this.readCount++
    return true
  }

  tryLock(): boolean {
    if (this.readCount > 0 || this.isWriting) {
      return false
    }
    this.isWriting = true
    return true
  }

  rLockWithTimeout(timeoutMs: number): boolean {
    const startTime = Bun.nanoseconds()

    while (this.isWriting || this.writePending > 0) {
      const elapsed = Bun.nanoseconds() - startTime
      if (elapsed >= timeoutMs * 1000000) {
        // 转换为纳秒
        return false
      }

      Bun.sleepSync(Math.min(this.spinDelay, timeoutMs))
    }

    this.readCount++
    return true
  }

  lockWithTimeout(timeoutMs: number): boolean {
    const startTime = Bun.nanoseconds()
    this.writePending++

    while (this.readCount > 0 || this.isWriting) {
      const elapsed = Bun.nanoseconds() - startTime
      if (elapsed >= timeoutMs * 1000000) {
        // 转换为纳秒
        this.writePending--
        return false
      }

      Bun.sleepSync(Math.min(this.spinDelay, timeoutMs))
    }

    this.writePending--
    this.isWriting = true
    return true
  }

  getState() {
    return {
      readCount: this.readCount,
      writePending: this.writePending,
      isWriting: this.isWriting,
    }
  }

  getPerformanceInfo() {
    return {
      runtime: 'Bun',
      hasNativeSync: true,
      hasHighPrecisionTimer: true,
      spinDelay: this.spinDelay,
    }
  }
}

export function withRLock<T>(mutex: RWMutex, fn: () => T): T {
  mutex.rLock()
  try {
    return fn()
  } finally {
    mutex.rUnlock()
  }
}

export function withLock<T>(mutex: RWMutex, fn: () => T): T {
  mutex.lock()
  try {
    return fn()
  } finally {
    mutex.unlock()
  }
}

export function withRLockTimeout<T>(mutex: RWMutex, timeoutMs: number, fn: () => T): T | null {
  if (!mutex.rLockWithTimeout(timeoutMs)) {
    return null
  }
  try {
    return fn()
  } finally {
    mutex.rUnlock()
  }
}

export function withLockTimeout<T>(mutex: RWMutex, timeoutMs: number, fn: () => T): T | null {
  if (!mutex.lockWithTimeout(timeoutMs)) {
    return null
  }
  try {
    return fn()
  } finally {
    mutex.unlock()
  }
}

export function getBunInfo() {
  return {
    version: Bun.version,
    hasNativeSync: true,
    hasNanoseconds: true,
  }
}
