  try {
    await sql.begin(async (tx) => {
      await tx`INSERT INTO test_table (id) VALUES (1)`;
      // Try to insert duplicate to trigger error
      await tx`INSERT INTO test_table (id) VALUES (1)`;
      // This should never run
      console.log("Should not reach here");
